from pathlib import Path
import json,csv
out=Path(__file__).resolve().parent
O=[]
def add(i,name,job,concept,support,rival,example,existing,tradeoff,dependence,fail):
 O.append(dict(option_id=i,direction=name,customer_job=job,concept=concept,support_evidence_ids=support,strongest_rival=rival,concrete_use_example=example,existing_capability_check=existing,tradeoffs=tradeoff,critical_dependencies=dependence,failure_condition=fail,status='conditional direction for user comparison; not selected',evidence_limit='Published facts support the mechanism, not an observed Auto2000 outcome or causal uplift.'))
add('MO01','Make service work and price understandable','Understand what is needed and what the final bill represents','Compare options that expose scope, provisional price, changes and completed work more clearly.',['M008','M009','M040'],'Most Auto2000 customers may already receive sufficient clarity.','An owner distinguishes the original estimate from work authorized later.','This is not a claim that quotes, records or photo documentation are absent.','More detail may increase cognitive load; estimates can legitimately change.','Reliable job status, scoped prices and branch records.','The issue is rare, obsolete, or caused by necessary work changes rather than unclear explanation.')
add('MO02','Clarify protection eligibility across lifecycle stages','Know which service or warranty benefit applies now','Explore clearer interpretation of existing T-CARE, XTRA and health-check terms.',['M014','M015','M016','M017'],'Owners may already understand and use benefits correctly.','A third-year owner checks whether the next service is covered or paid and what protection follows.','Toyota already publishes these programs; this is not a new warranty proposal.','Simplification can hide exclusions or create entitlement disputes.','Current OEM rules, vehicle age/mileage and entitlement accuracy.','No material misunderstanding or reachable eligible group is found.')
add('MO03','Connect home-charging intention to practical readiness','Know whether a BEV fits the household','Explore use-specific guidance connecting residential conditions to existing PLN/partner routes.',['M004','M019','M035'],'Public/shared charging may already fit the customer’s life.','An apartment resident separates preferred home charging from actual installation access.','PLN offers official routes; CarMax demonstrates a partner-support mechanism abroad.','Guidance can become stale and cannot replace a qualified installation assessment.','Local utility/building conditions, compatible model and accurate partner information.','The binding constraint is vehicle price or building permission, beyond information.')
add('MO04','Differentiate ownership information by powertrain and work due','Understand what care a specific vehicle needs','Explore separate HEV, PHEV and BEV ownership explanations rather than generic EV routines.',['M011','M012','M013'],'Current model-specific materials may already be adequate.','A hybrid owner sees why its engine-service needs differ from a BEV.','Manufacturer schedules remain the authority.','Too many categories can complicate navigation; model variation persists.','Verified local model schedules and clearly defined jobs.','Current experience already supplies the right answer or owners rely effectively on advisers.')
add('MO05','Preserve relationship context across ownership tasks','Use trusted service knowledge when buying, maintaining or replacing','Compare ways to make relevant history and protection context intelligible across customer tasks.',['M010','M021','M037'],'Customers may intentionally prefer separate dealer relationships.','An owner reviews which prior service evidence matters to a replacement decision.','Toyota UK describes portable warranty records; local equivalent must be checked.','Portability adds data-quality and privacy obligations; relationship concentration may not benefit every owner.','Relevant permissions, accurate records and clearly defined roles.','No meaningful continuity gap or lawful/usable data source exists.')
add('MO06','Explain how a trade-in estimate becomes an inspected offer','Plan replacement without mistaking an estimate for a guarantee','Explore clearer explanation of appraisal uncertainty, condition evidence and remaining obligations.',['M003','M021','M046'],'The customer may reject a fair price even when the process is understood.','A seller sees why condition evidence changes an initial online range.','OLXmobbi already differentiates estimate from final condition-based value.','Honest ranges may feel less decisive; a guarantee transfers real residual risk.','Current appraisal terms and partner evidence; no invented resale floor.','The constraint is a lower market valuation rather than information clarity.')
add('MO07','Compare purchase and subscription on total obligations','Choose a mobility arrangement that fits cash flow and use','Explore comparisons including cash, ownership, included items and remaining liabilities.',['M003','M044','M045'],'A customer may prefer ownership or find neither arrangement affordable.','A driver compares predictable payments with mileage limits and end-of-term ownership differences.','KINTO already exists; no proposal to recreate it or assume fleet eligibility.','Lower visible upfront cost may accompany a higher total cost or restrictions.','Actual comparable offers, mileage/use and partner terms.','No suitable vehicle/contract is available or the customer needs unsupported commercial use.')
add('MO08','Distinguish credit exploration from final approval','Know what financing information is indicative and what is committed','Explore continuity between simulations, eligibility indications and a verified partner offer.',['M032','M047'],'Income, underwriting or affordability may dominate interface friction.','A buyer understands that a simulated installment is not a final approved loan.','SEVA already advertises simulation and approval-related functions.','More qualification can protect accuracy while adding effort.','Partner terms, quote assumptions, consent and clear decision responsibility.','Actual underwriting rejects the buyer or existing handoffs already work.')
add('MO09','Support the customer’s preferred assisted route','Resolve exceptions without repeating the whole task','Compare connected self-service and adviser routes rather than assuming all-online completion.',['M031','M032','M041'],'Some segments genuinely prefer complete self-service.','A shopper carries their model comparison into an adviser conversation.','Digiroom and OEM/partner capabilities must be mapped before claiming a gap.','Human assistance consumes capacity and may add dependency; self-service can be faster for simple tasks.','Clear context ownership and a functioning assistance route.','The real issue is stock, price or response capacity rather than lost context.')
add('MO10','Explain battery evidence together with protection and limitations','Judge a used or aging electrified vehicle','Compare how condition information, uncertainty and warranty responsibility are communicated together.',['M015','M021','M033','M034','M038'],'Battery condition may be acceptable while price or product fit remains unattractive.','A prospective used buyer reads a condition report without treating it as a resale guarantee.','Toyota health checks and foreign marketplace reports already exist.','A simple score can hide uncertainty; a detailed report can overwhelm.','Valid model-specific diagnostics, report scope and protection terms.','No reliable evidence is available or information does not alter the customer’s binding concern.')
add('MO11','Frame vehicle choice around practical use trade-offs','Choose a vehicle appropriate to actual journeys and budget','Explore comparisons of acquisition cost, charging time, operating conditions and model fit.',['M003','M004','M024'],'Customers may already know their preferred model or prioritize status/brand.','A buyer considering a BEV compares home access and frequent intercity use with a hybrid alternative.','Comparison tools may already list specifications; incremental decision value must be tested.','More personalized inputs add effort and can imply precision unsupported by real use data.','Comparable variant/location/period offers and transparent assumptions.','No suitable Toyota option exists or the price difference dominates.')
add('MO12','Recognize successful quiet periods in ownership','Get help when a meaningful need arises','Explore an ownership proposition organized around actual jobs rather than compulsory frequent opening.',['M011','M012','M016','M017'],'Frequent useful contact may independently build trust or retention.','An owner returns for an eligible service or replacement question after months without app use.','Existing benefits and channels may already support these occasions.','Lower interaction frequency reduces marketing inventory but can respect customer effort.','Job cadence, service entitlement and actual completion data for business evaluation.','Evidence shows valuable recurring use has an incremental effect or customers miss needed care.')
(out/'solution_directions.json').write_text(json.dumps(O,ensure_ascii=False,indent=2))
with (out/'solution_directions.csv').open('w',newline='',encoding='utf8') as f:
 w=csv.DictWriter(f,fieldnames=list(O[0]));w.writeheader();w.writerows({**x,'support_evidence_ids':'|'.join(x['support_evidence_ids'])} for x in O)
print('options',len(O))
